async def handle_send(user_id: str, frame: dict, db, router, notify) -> dict:
    """Runs on the single owner of frame['conv_id'] (consistent hashing),
    so sequence numbers per conversation are assigned one at a time."""
    conv, cmid = frame["conv_id"], frame["client_msg_id"]
    if not await db.is_member(conv, user_id):
        return {"type": "error", "client_msg_id": cmid, "code": "forbidden"}
    # A retry of a message we already stored: same seq back, nothing new
    seq = await db.seq_for_client_id(conv, cmid)
    if seq is not None:
        return {"type": "ack", "client_msg_id": cmid, "seq": seq}
    seq = await db.next_seq(conv)                      # gap-free per conversation
    await db.insert_message(conv, seq, user_id, cmid, frame["body"])  # persist first
    # Small groups: route per member. Big channels fan out via gateway subscriptions.
    for member in await db.members(conv):
        if member == user_id:
            continue
        gateway = await router.gateway_of(member)      # None when offline
        if gateway:
            await gateway.push(member, {"type": "msg", "conv_id": conv, "seq": seq})
        else:
            await notify.enqueue(member, conv, seq)    # push via APNs / FCM
    return {"type": "ack", "client_msg_id": cmid, "seq": seq}

def on_message(last_seq: dict, msg: dict, sync):
    """Client: drop duplicates, detect gaps, resync from the last contiguous seq."""
    last = last_seq.get(msg["conv_id"], 0)
    if msg["seq"] <= last:
        return                                         # duplicate delivery
    if msg["seq"] > last + 1:
        sync(msg["conv_id"], after_seq=last)           # missed some: fetch them
        return
    last_seq[msg["conv_id"]] = msg["seq"]
    render(msg)
